import{_ as t,o as r,c as i,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const d=JSON.parse('{"title":"Pillar 3: Swarm Architecture","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"Pillar 3: Swarm Architecture","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/pillar-3-swarm-architecture.md","filePath":"framework/pillar-3-swarm-architecture.md"}'),o={name:"framework/pillar-3-swarm-architecture.md"};function s(n,e,l,c,h,p){return r(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="pillar-3-swarm-architecture" tabindex="-1">Pillar 3: Swarm Architecture <a class="header-anchor" href="#pillar-3-swarm-architecture" aria-label="Permalink to &quot;Pillar 3: Swarm Architecture&quot;">​</a></h3><p><strong>Purpose:</strong> Prevent context degradation by splitting development tasks across three explicit agent roles, each with hard constraints that prevent scope creep.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;👷 /architect&quot;] --&gt;|&quot;Approved Plan&quot;| B[&quot;🔨 /builder&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|&quot;Tests Pass&quot;| C[&quot;🔍 /reviewer&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|&quot;Bugs Found&quot;| B</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|&quot;Approved&quot;| D[&quot;✅ Deploy&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|&quot;Architecture Flaw&quot;| A</span></span></code></pre></div><h4 id="role-1-the-architect-architect" tabindex="-1">Role 1: The Architect (<code>/architect</code>) <a class="header-anchor" href="#role-1-the-architect-architect" aria-label="Permalink to &quot;Role 1: The Architect (`/architect`)&quot;">​</a></h4><p><strong>Constraint:</strong> No production code is written. Output is an <code>implementation_plan.md</code> artifact containing:</p><ol><li><strong>Step-by-step breakdown</strong> — logical, sequential steps.</li><li><strong>Schema &amp; contract changes</strong> — explicit modifications to databases, APIs, or data models.</li><li><strong>Edge case identification</strong> — at least 3 potential failure modes.</li><li><strong>TDD definitions</strong> — the tests that must exist before implementation.</li><li><strong>Security audit check</strong> — mandatory reference to the security rules auditor skill.</li></ol><p><strong>Gate:</strong> The human developer must explicitly approve the plan before the Builder begins.</p><h4 id="role-2-the-builder-builder" tabindex="-1">Role 2: The Builder (<code>/builder</code>) <a class="header-anchor" href="#role-2-the-builder-builder" aria-label="Permalink to &quot;Role 2: The Builder (`/builder`)&quot;">​</a></h4><p><strong>Constraints:</strong></p><ul><li><strong>No re-architecting.</strong> If the plan is flawed, STOP and request a re-invocation of the Architect. Do not silently deviate.</li><li><strong>Mandatory TDD.</strong> Write the failing test first, then implement logic.</li><li><strong>No self-review.</strong> When tests pass, hand off to the Reviewer. Do not attempt to QA your own code.</li></ul><h4 id="role-3-the-reviewer-reviewer" tabindex="-1">Role 3: The Reviewer (<code>/reviewer</code>) <a class="header-anchor" href="#role-3-the-reviewer-reviewer" aria-label="Permalink to &quot;Role 3: The Reviewer (`/reviewer`)&quot;">​</a></h4><p><strong>Constraints:</strong></p><ul><li><strong>Adversarial mindset.</strong> Do not trust the Builder&#39;s tests. Write hostile tests designed to break the code.</li><li><strong>Security first.</strong> Cross-reference the security rules auditor skill.</li><li><strong>No feature implementation.</strong> If a bug is found, write a failing test to prove it, then instruct the Builder to fix it.</li><li><strong>Sign-off authority.</strong> Only the Reviewer can mark a task as &quot;Approved for Deployment.&quot;</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>The Self-Review Anti-Pattern:</strong> Allowing the same agent session to both write code and review it is equivalent to asking a developer to peer-review their own pull request. The agent will confirm its own assumptions rather than challenging them. The Reviewer role must operate with a distinct adversarial prompt that treats the Builder&#39;s output as untrusted input.</p></div><hr>',15)])])}const g=t(o,[["render",s]]);export{d as __pageData,g as default};
